create table if not exists market_price_observation (id uuid primary key default gen_random_uuid(), master_product_id uuid not null references master_product(id) on delete cascade, product_variant_id uuid references product_variant(id) on delete set null, source text not null, source_product_id text, sale_price numeric(14,2) not null check (sale_price >= 0), payment_fee numeric(14,2), marketplace_fee numeric(14,2), tax numeric(14,2), other_cost numeric(14,2), sold boolean not null default false, source_url text, observed_at timestamptz not null default now(), created_at timestamptz not null default now()); create index if not exists idx_market_price_master_observed on market_price_observation(master_product_id, observed_at desc); alter table market_price_observation enable row level security;